CREATE TABLE v54124 (v54125 DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), v54126 DATETIME(6) NULL DEFAULT NULL, PRIMARY KEY (v54125, B(1))) AS SELECT TIMESTAMP('2001-01-01 10:10:10'), TIMESTAMP(CONCAT('2001-01-01 00:01:01', '.123')), TIMESTAMP('0000-00-01'), TIMESTAMP('2001-01-01 10:10:10.123456')